def transform(grid):
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]

    walls = [
        r for r in range(h)
        if sum(v == 8 for v in grid[r]) >= w // 2
        and all(v in (0, 8) for v in grid[r])
    ]

    # Extend the marker toward the first horizontal barrier.
    seeds = [(r, c) for r in range(h) for c in range(w) if grid[r][c] == 2]
    if seeds and walls:
        sr, sc = seeds[0]
        first = walls[0]
        for r in range(sr + 1, first):
            if out[r][sc] == 0:
                out[r][sc] = 2

        # First barrier's opening is linked to the marker column by a
        # symmetric horizontal segment.
        gaps = [c for c, v in enumerate(grid[first]) if v == 0]
        if gaps and first > 0:
            if len(gaps) == 1:
                lo, hi = min(sc, gaps[0] - (sc - gaps[0])), max(sc, gaps[0] + (sc - gaps[0]))
                lo, hi = max(0, lo), min(w - 1, hi)
            else:
                lo, hi = min(gaps), max(gaps)
            for c in range(lo, hi + 1):
                if out[first - 1][c] == 0:
                    out[first - 1][c] = 2

    for i, r in enumerate(walls):
        gaps = [c for c, v in enumerate(grid[r]) if v == 0]
        if not gaps:
            continue

        stop = walls[i + 1] if i + 1 < len(walls) else h
        for c in gaps:
            for rr in range(r, stop):
                if out[rr][c] == 0:
                    out[rr][c] = 2

        if r > 0 and i > 0:
            lo, hi = min(gaps), max(gaps)
            for c in range(lo, hi + 1):
                if out[r - 1][c] == 0:
                    out[r - 1][c] = 2

    return out
